style.css:
/* Stylish Theme: Cool Car Background */
@namespace url("http://www.w3.org/1999/xhtml");
@-moz-document url-prefix("http://"), url-prefix("https://") {
body {
    background: url("https://hdqwalls.com/wallpapers/koenigsegg-agera-2.jpg") no-repeat center center fixed;
    background-size: cover;
  }

  /* Set all text to black with high specificity */
  *, *::before, *::after {
    color: black !important; /* Force black text for all elements */
    text-shadow: none !important; /* Remove any shadows that might make text look gray */
    background: transparent !important; /* Ensure no background interferes with text */
  }

  /* Override link colors */
  a {
    color: black !important; /* Make links black */
    text-decoration: none !important; /* Remove underlines for a cleaner look */
  }

  a:hover {
    color: darkgray !important; /* Slight hover effect for clarity */
  }

  /* Remove any additional overlays */
  body::before, body::after {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: none !important; /* Ensure no overlay obstructs text or design */
    z-index: -1;
  }
}
